export const EXAMPLE_PROJECT = {"id":"00000000-0000-4000-8000-000000000001","name":"Electrocatalysis Must-Reads","is_template":true,"description":"196 papers in six rings, from the foundations every catalysis field shares out to the frontier of electrocatalysis. Start with the 14-paper first pass, then read each ring from the centre out, starred papers first.","sections":[{"id":"found","name":"The foundations","sub":"Rates, sites, alloys and electron transfer","blurb":"The ideas that thermal catalysis, surface science and electrochemistry all rest on: turnover rates, structure sensitivity, ensembles, the degree of rate control, and Marcus-type electron transfer. Most of these predate electrocatalysis as a field, and the best electrocatalysis papers assume you know them."},{"id":"core","name":"The surface","sub":"Adsorption, descriptors and model surfaces","blurb":"The vocabulary the rest of the field is written in: the d-band model, scaling relations, volcano plots, the computational hydrogen electrode, and what single crystals, oxide films and single-atom alloys teach about real sites."},{"id":"rxn","name":"The reactions","sub":"Hydrogen, oxygen and carbon","blurb":"The three reaction families that define electrocatalysis. Read the hydrogen papers first. HER is the simplest case where the descriptor idea works, OER/ORR show what scaling relations cost you, and CO2/CO reduction is where selectivity becomes the main problem."},{"id":"intf","name":"The interface","sub":"Cations, solvent, fields, confinement and local concentration","blurb":"Everything on the liquid side of the catalyst. This ring mixes electrochemistry with thermal catalysis in water and in pores, because the same solvation, confinement and proton-transfer ideas apply. These papers bear most directly on any question about local CO concentration."},{"id":"rigor","name":"The measurement","sub":"Protocols, site counting, kinetic analysis, stability","blurb":"How to produce numbers that someone else can trust and compare. These are the papers a committee will expect you to have absorbed before you report a Faradaic efficiency, a turnover frequency or a Tafel slope."},{"id":"front","name":"The frontier","sub":"Single sites, dynamics, data, light and scale","blurb":"Where catalysis is moving: sites that form or move under reaction conditions, catalysts driven by oscillating potentials or light, single-atom and molecular catalysts like CoPc, constant-potential theory, machine-learned screening, and high-current electrolysers."}],"meta":{"firstPass":["4b1e6de8-bf88-52e9-9464-a2ed9a2eed16","f1757445-84bc-5244-b742-ded3fe605a93","58854714-30a1-56a6-849e-7a2131e0ba88","a79e028c-93ca-5c7e-b368-5307109faff9","f1f26559-c6f5-5f0e-adbc-fa09ee0cedfa","27770e1d-ad95-5e8b-a4c7-f44c6e862d17","dcf68675-51b7-58ac-8974-521cc5462e44","1704f9f1-c088-52c9-9cb3-ccfc893a4e67","67424bad-f87f-567b-9218-f693142efc1a","913c4aa7-a1ca-5d3b-8997-bcced91cf9b6","4d8c8d8d-c5f9-5604-a7c4-061722556d13","ac1744e9-2419-5b77-9608-6f7f1487f81e","15d7fa31-2059-5f74-aee7-39580f6821c8","b41ca489-3f09-5966-8ea7-37ee75cad085"]}};
